(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-378":{scenario:{company:"Lotus Dew Skincare",supervisor:{name:"Ngô Thùy Dương",role:{vi:"Trưởng phòng CRM & Marketing tự động",en:"CRM & Marketing Automation Manager"}},ref_code:"JRN-7714",title:{vi:"Đúng người đồng ý. Đúng doanh thu tăng thêm.",en:"Right consent. Right incremental revenue."},brief:{vi:"Bạn cấu hình đợt 2 hành trình tái kích hoạt JRN-7714, chỉ nhắm khách đã đồng ý nhận tin tiếp thị nhưng không mở email 90 ngày; bản nháp chọn phân khúc ALL-INACTIVE90 (gồm cả liên hệ chưa đồng ý và đã hủy đăng ký). Kết quả đợt 1: nhóm nhận tin 18000 liên hệ có 540 đơn; nhóm đối chứng 2000 liên hệ không nhận tin có 40 đơn; giá trị đơn trung bình 400 nghìn đồng (mô phỏng). Sửa phân khúc và doanh thu tăng thêm (triệu đồng), rồi lập báo cáo có căn cứ.",en:"You are configuring wave 2 of win-back journey JRN-7714, targeting only customers who gave marketing consent but have not opened an email in 90 days; the draft selects segment ALL-INACTIVE90 (including non-consented and unsubscribed contacts). Wave 1 results: the treated group of 18000 contacts placed 540 orders; the 2000-contact holdout placed 40; average order value 400 thousand VND (training data). Correct the segment and the incremental revenue (million VND), then write an evidence-based report."},reference_title:{vi:"Đặc tả phân khúc & báo cáo đối chứng đã duyệt · JRN-7714",en:"Approved segment spec & holdout report · JRN-7714"},fields:[{id:"SEGMENT",label:{vi:"Phân khúc gửi đợt 2",en:"Wave 2 send segment"},initial:"ALL-INACTIVE90",expected:"OPTIN-INACTIVE90",choices:["ALL-INACTIVE90","OPTIN-INACTIVE90","OPTIN-ACTIVE30"],reference:"Đặc tả phân khúc hành trình",hint:{vi:"Tin tiếp thị chỉ gửi cho liên hệ có đồng ý hợp lệ và chưa hủy; mục tiêu đợt này là nhóm không mở email 90 ngày.",en:"Marketing messages go only to contacts with valid, unrevoked consent; this wave targets the 90-day non-openers."}},{id:"INCR_REV",label:{vi:"Doanh thu tăng thêm đợt 1 (triệu đồng)",en:"Wave 1 incremental revenue (million VND)"},initial:"216",expected:"72",reference:"Báo cáo nhóm nhận tin / đối chứng",ref_value:{vi:"Nhận tin 18000 liên hệ - 540 đơn; đối chứng 2000 - 40 đơn; AOV 0,4 triệu đồng",en:"Treated 18000 contacts - 540 orders; holdout 2000 - 40 orders; AOV 0.4 million VND"},hint:{vi:"Không gán toàn bộ đơn hàng cho chiến dịch; phải trừ phần khách vẫn mua khi không nhận tin.",en:"Do not credit every order to the campaign; subtract what customers buy without the message."}}],sop32:{vi:"Đơn tăng thêm = (tỷ lệ mua nhóm nhận tin - tỷ lệ mua nhóm đối chứng) x số liên hệ nhóm nhận tin; doanh thu tăng thêm = đơn tăng thêm x giá trị đơn trung bình.",en:"Incremental orders = (treated purchase rate - holdout purchase rate) x treated contacts; incremental revenue = incremental orders x average order value."},context:{label:"CRM AUTOMATION / JRN-7714",metrics:[{label:{vi:"Tỷ lệ mua nhóm nhận tin",en:"Treated purchase rate"},value:"3.0%"},{label:{vi:"Tỷ lệ mua nhóm đối chứng",en:"Holdout purchase rate"},value:"2.0%"},{label:{vi:"Giá trị đơn trung bình",en:"Average order value"},value:"400k VND"}]},crisis:{vi:"Giám đốc kinh doanh gửi tệp 20000 số điện thoại và email mua từ bên ngoài: “Nhập hết vào hành trình, tối nay bắn SMS và email khuyến mại luôn, cần doanh số cuối tháng.”",en:"The sales director sends a file of 20000 phone numbers and emails bought from a third party: “Import them all into the journey and blast promo SMS and emails tonight, we need month-end sales.”"},options:{safe:{vi:"Từ chối nhập dữ liệu không có đồng ý hợp lệ, báo trưởng phòng CRM và bộ phận bảo vệ dữ liệu; đề xuất thu thập khách tiềm năng có đồng ý qua biểu mẫu xác nhận hai bước.",en:"Refuse to import data without valid consent, inform the CRM Manager and the data protection officer; propose consented lead capture through a double opt-in form."},shortcut:{vi:"Nhập tệp vào phân khúc riêng, gửi một lần rồi xóa để tránh bị phát hiện.",en:"Import the file into a separate segment, send once and delete it to avoid detection."},wait:{vi:"Để tệp trong hộp thư, không trả lời và chờ giám đốc tự nhập.",en:"Leave the file in the inbox, do not reply and wait for the director to import it."}},questions:{vi:["Vì sao phân khúc đúng là OPTIN-INACTIVE90? Hãy nêu căn cứ về sự đồng ý và tiêu chí hành vi.","Trình bày cách tính doanh thu tăng thêm 72 triệu đồng và rủi ro pháp lý nếu gửi tin cho dữ liệu mua ngoài."],en:["Why is OPTIN-INACTIVE90 the correct segment? State the consent basis and behavioral criteria.","Explain how you reached 72 million VND of incremental revenue and the legal risk of messaging bought data."]},hints:{vi:["Đọc đặc tả phân khúc: lọc trạng thái đồng ý trước, rồi mới lọc hành vi mở email.","Theo SOP mục 3.2, so tỷ lệ mua của nhóm nhận tin với nhóm đối chứng trước khi nhân giá trị đơn.","Đọc SOP mục 4.2: dữ liệu cá nhân không rõ nguồn gốc và không có đồng ý không được nhập vào hệ thống."],en:["Read the segment spec: filter consent status first, then email-open behavior.","Per SOP 3.2, compare treated and holdout purchase rates before multiplying by order value.","Read SOP 4.2: personal data of unknown origin and without consent must never enter the system."]}},learning:{summary:{vi:"Chuyên viên CRM & Marketing tự động hóa xây dựng và vận hành các hành trình khách hàng tự động qua email, SMS, thông báo ứng dụng và tin nhắn OTT: chào mừng, nuôi dưỡng, bỏ giỏ hàng, tái kích hoạt, chăm sóc sau mua. Nghề kết hợp phân khúc dữ liệu, thiết kế kịch bản, đo lường bằng nhóm đối chứng và quản trị sự đồng ý để tăng giá trị vòng đời khách hàng mà vẫn tuân thủ pháp luật về dữ liệu cá nhân và chống tin rác.",en:"A CRM & Marketing Automation Specialist builds and runs automated customer journeys across email, SMS, app push and messaging apps: welcome, nurture, cart abandonment, win-back and post-purchase care. The role combines data segmentation, journey design, holdout-based measurement and consent management to grow customer lifetime value while complying with personal data and anti-spam rules."},responsibilities:{vi:["Thiết kế hành trình tự động theo vòng đời khách hàng và điều kiện kích hoạt rõ ràng.","Xây phân khúc theo RFM, hành vi và trạng thái đồng ý; duy trì danh sách loại trừ.","Viết, kiểm thử nội dung đa kênh và kiểm soát tần suất gửi cho mỗi khách hàng.","Đo hiệu quả bằng nhóm đối chứng, tính doanh thu tăng thêm và tối ưu kịch bản.","Quản trị chất lượng dữ liệu, xác thực tên miền gửi thư và tuân thủ quy định dữ liệu cá nhân."],en:["Design lifecycle-based automated journeys with clear entry triggers.","Build segments by RFM, behavior and consent status; maintain suppression lists.","Write and test multichannel content and control message frequency per customer.","Measure with holdout groups, compute incremental revenue and optimize journeys.","Govern data quality, sender domain authentication and personal data compliance."]},competencies:[{name:{vi:"Phân khúc & dữ liệu khách hàng",en:"Segmentation & customer data"},desc:{vi:"Ghép dữ liệu giao dịch, hành vi, sự đồng ý thành phân khúc có thể hành động và cập nhật tự động.",en:"Combine transaction, behavior and consent data into actionable, auto-updating segments."}},{name:{vi:"Thiết kế hành trình",en:"Journey design"},desc:{vi:"Xây luồng kích hoạt, rẽ nhánh, thời gian chờ và điều kiện thoát hợp lý.",en:"Build triggers, branches, wait steps and sensible exit conditions."}},{name:{vi:"Đo lường tăng trưởng thực",en:"Incrementality measurement"},desc:{vi:"Dùng nhóm đối chứng để tách doanh thu do chiến dịch tạo ra khỏi doanh thu tự nhiên.",en:"Use holdouts to separate campaign-driven revenue from organic revenue."}},{name:{vi:"Khả năng gửi thư",en:"Deliverability"},desc:{vi:"Cấu hình SPF, DKIM, DMARC, giữ danh sách sạch và tỷ lệ khiếu nại thấp.",en:"Configure SPF, DKIM and DMARC and keep clean lists and low complaint rates."}},{name:{vi:"Quản trị sự đồng ý",en:"Consent governance"},desc:{vi:"Ghi nhận, lưu bằng chứng, tôn trọng việc rút đồng ý và từ chối dữ liệu không rõ nguồn gốc.",en:"Record and evidence consent, honor withdrawals and reject data of unknown origin."}}],knowledge:{vi:["Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân và Luật Bảo vệ dữ liệu cá nhân có hiệu lực từ 01/01/2026.","Nghị định 91/2020/NĐ-CP về chống tin nhắn rác, thư điện tử rác, cuộc gọi rác.","Xác thực thư điện tử SPF, DKIM, DMARC và hủy đăng ký một chạm theo RFC 8058.","Phân khúc RFM (gần đây, tần suất, giá trị) và mô hình vòng đời khách hàng.","Thiết kế thử nghiệm A/B và nhóm đối chứng, cách tính doanh thu tăng thêm."],en:["Decree 13/2023/ND-CP on personal data protection and the Personal Data Protection Law effective 1 January 2026.","Decree 91/2020/ND-CP on combating spam messages, spam emails and spam calls.","Email authentication with SPF, DKIM, DMARC and one-click unsubscribe under RFC 8058.","RFM segmentation (recency, frequency, monetary) and customer lifecycle models.","A/B test and holdout design and how to compute incremental revenue."]},tools:["Nền tảng CRM / CDP","Công cụ marketing tự động hóa","Cổng gửi SMS & tin nhắn OTT","SQL","Công cụ kiểm tra hiển thị & khả năng gửi email","Looker Studio / BI"],kpis:{vi:["Doanh thu tăng thêm đo bằng nhóm đối chứng của từng hành trình.","Tỷ lệ mở, nhấp, chuyển đổi và tỷ lệ hủy đăng ký theo kênh.","Tỷ lệ thư bị trả về và tỷ lệ khiếu nại spam dưới ngưỡng cho phép.","Tỷ lệ liên hệ có bằng chứng đồng ý hợp lệ trong cơ sở dữ liệu (mục tiêu 100%)."],en:["Holdout-measured incremental revenue per journey.","Open, click, conversion and unsubscribe rates by channel.","Bounce and spam complaint rates below allowed thresholds.","Share of contacts with valid consent evidence in the database (target 100%)."]},day:[{time:"08:30",vi:"Kiểm tra nhật ký gửi đêm qua, tỷ lệ trả về, khiếu nại và lỗi kích hoạt hành trình.",en:"Check last night's send logs, bounces, complaints and journey trigger errors."},{time:"10:00",vi:"Viết truy vấn SQL dựng phân khúc mới và đối chiếu trạng thái đồng ý.",en:"Write SQL for a new segment and reconcile consent status."},{time:"13:30",vi:"Kiểm thử nội dung email, SMS trên nhiều thiết bị và luồng rẽ nhánh.",en:"Test email and SMS content across devices and branching logic."},{time:"15:30",vi:"Phân tích kết quả nhóm nhận tin so với đối chứng, cập nhật doanh thu tăng thêm.",en:"Analyze treated versus holdout results and update incremental revenue."},{time:"17:00",vi:"Họp nhanh với bộ phận dữ liệu về yêu cầu rút đồng ý và danh sách loại trừ.",en:"Sync with the data team on consent withdrawals and suppression lists."}],mistakes:{vi:["Gửi tin tiếp thị cho liên hệ chưa đồng ý hoặc đã hủy đăng ký.","Gán toàn bộ doanh thu của người nhận tin cho chiến dịch mà không có nhóm đối chứng.","Nhập danh sách mua ngoài vào hệ thống, làm hỏng uy tín tên miền gửi và vi phạm pháp luật."],en:["Sending marketing messages to non-consented or unsubscribed contacts.","Crediting all recipient revenue to the campaign without a holdout group.","Importing bought lists, damaging sender reputation and breaking the law."]},career:[{vi:"Nhân viên vận hành CRM / email marketing",en:"CRM / Email Marketing Executive"},{vi:"Chuyên viên CRM & Marketing tự động hóa",en:"CRM & Marketing Automation Specialist"},{vi:"Trưởng nhóm CRM & vòng đời khách hàng",en:"CRM & Lifecycle Marketing Lead"},{vi:"Giám đốc CRM & Dữ liệu khách hàng",en:"Head of CRM & Customer Data"}],glossary:[{term:"Opt-in",vi:"Sự đồng ý chủ động của khách hàng cho phép nhận thông tin tiếp thị qua một kênh cụ thể.",en:"A customer's active consent to receive marketing messages through a given channel."},{term:"Holdout group",vi:"Nhóm đối chứng được giữ lại không nhận tin để đo tác động thực của chiến dịch.",en:"A control group kept from receiving messages to measure the campaign's true impact."},{term:"RFM",vi:"Phân khúc theo mức gần đây, tần suất và giá trị mua hàng của khách.",en:"Segmentation by recency, frequency and monetary value of purchases."},{term:"DMARC",vi:"Chính sách xác thực tên miền gửi thư dựa trên SPF và DKIM, chống giả mạo người gửi.",en:"A sender domain authentication policy built on SPF and DKIM that fights spoofing."},{term:"Suppression list",vi:"Danh sách liên hệ bị loại khỏi mọi lần gửi do hủy đăng ký, khiếu nại hoặc địa chỉ lỗi.",en:"Contacts excluded from all sends due to unsubscribes, complaints or invalid addresses."}],quiz:[{q:{vi:"Nhóm nhận tin 10000 liên hệ có 400 đơn, nhóm đối chứng 1000 liên hệ có 30 đơn. Số đơn tăng thêm là bao nhiêu?",en:"The treated group of 10000 contacts placed 400 orders; the 1000-contact holdout placed 30. How many incremental orders?"},options:{vi:["400","370","300","100"],en:["400","370","300","100"]},answer:3,explain:{vi:"(4% - 3%) x 10000 = 100 đơn tăng thêm; 300 đơn còn lại khách vẫn mua khi không nhận tin.",en:"(4% - 3%) x 10000 = 100 incremental orders; the other 300 would have happened anyway."}},{q:{vi:"Liên hệ đã hủy đăng ký email tháng trước có được đưa vào chiến dịch khuyến mại mới không?",en:"Can a contact who unsubscribed last month be added to a new promotional campaign?"},options:{vi:["Có, nếu là khách VIP","Không, phải tôn trọng việc rút đồng ý","Có, nếu gửi qua SMS thay email","Có, sau 30 ngày"],en:["Yes, if they are VIP","No, the withdrawal must be honored","Yes, via SMS instead of email","Yes, after 30 days"]},answer:1,explain:{vi:"Rút đồng ý có hiệu lực cho đến khi khách tự đồng ý lại; đổi kênh không hợp thức hóa việc gửi.",en:"Withdrawal stands until the customer consents again; switching channels does not make it lawful."}},{q:{vi:"Bản ghi DNS nào cho phép tên miền công bố chính sách xử lý thư giả mạo?",en:"Which DNS record lets a domain publish a policy for spoofed mail?"},options:{vi:["DMARC","MX","CNAME","AAAA"],en:["DMARC","MX","CNAME","AAAA"]},answer:0,explain:{vi:"DMARC dựa trên kết quả SPF, DKIM để chỉ định cách xử lý thư không xác thực.",en:"DMARC uses SPF and DKIM results to specify how unauthenticated mail is handled."}},{q:{vi:"Cấp trên đưa tệp dữ liệu mua ngoài và yêu cầu gửi SMS khuyến mại ngay. Bạn làm gì?",en:"A manager hands you a bought data file and asks for promo SMS right away. What do you do?"},options:{vi:["Gửi thử 1000 số trước","Gửi qua tài khoản cá nhân","Từ chối, báo bộ phận bảo vệ dữ liệu và đề xuất thu thập có đồng ý","Gửi nhưng thêm dòng hủy đăng ký"],en:["Test on 1000 numbers first","Send from a personal account","Refuse, inform data protection and propose consented capture","Send but add an opt-out line"]},answer:2,explain:{vi:"Dữ liệu không có đồng ý hợp lệ không được dùng để tiếp thị; dòng hủy đăng ký không thay thế sự đồng ý.",en:"Data without valid consent cannot be used for marketing; an opt-out line does not replace consent."}}],tools_en:["CRM / CDP platform","Marketing automation tools","SMS & OTT messaging gateway","SQL","Email rendering & deliverability testing tools","Looker Studio / BI"]}}})})(window.KKR);
